function dump(node, depth){
  if(depth>4) return null;
  const o = {id:node.id, name:node.name, type:node.type, w:Math.round(node.width), h:Math.round(node.height)};
  if(node.type==='TEXT'){o.chars=node.characters; o.fontName=node.fontName; o.fontSize=node.fontSize; o.fills=node.fills;}
  if('cornerRadius' in node) o.cornerRadius=node.cornerRadius;
  if('fills' in node && node.type!=='TEXT') o.fills=node.fills;
  if('strokes' in node) {o.strokes=node.strokes; o.strokeWeight=node.strokeWeight;}
  if('children' in node) o.children=node.children.map(c=>dump(c,depth+1)).filter(Boolean);
  return o;
}
